and r.receipt_no like concat('%',#{receiptNo},'%')
and r.receipt_type=#{receiptType}
and r.warehouse_id=#{warehouseId}
and r.supplier_name like concat('%',#{supplierName},'%')
and r.status=#{status}
and r.receipt_date=#{receiptDate}
and r.receipt_date >= #{params.beginTime}
and r.receipt_date < date_add(#{params.endTime}, interval 1 day)
 order by r.receipt_date desc,r.receipt_id desc

